package com.eye.reminder;
import java.nio.file.*;
import java.util.*;
public final class ReminderOrganizationAcceptance {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static void tick(ReminderManager manager)throws Exception{var method=ReminderManager.class.getDeclaredMethod("tick");method.setAccessible(true);method.invoke(manager);}
 public static void main(String[] args)throws Exception{
  Path root=Files.createTempDirectory("EyeRelax-reminder-organization-");System.setProperty("user.home",root.toString());ReminderStore store=new ReminderStore(root.resolve("reminders.properties"));ReminderManager manager=new ReminderManager(store);List<ReminderItem> deliveries=new ArrayList<>();manager.setDueHandler(deliveries::add);
  ReminderItem once=new ReminderItem();once.title="一次喝水";once.nextTriggerEpochMs=System.currentTimeMillis()-1;manager.upsert(once);tick(manager);ReminderItem fired=deliveries.get(0);check(manager.get(once.id).awaitingCompletion&&manager.get(once.id).lifecycle==ReminderItem.Lifecycle.CURRENT,"trigger alone does not mean completion");
  ReminderManager restart=new ReminderManager(store);int[] recovered={0};restart.setDueHandler(item->{recovered[0]++;restart.completePresentation(item);});restart.start();check(recovered[0]==1&&restart.get(once.id).lifecycle==ReminderItem.Lifecycle.COMPLETED,"pending final overlay resumes after restart and closes into archive");restart.shutdown();manager.completePresentation(fired);check(ReminderPanel.category(manager.get(once.id))==2,"completed absent from active list");
  ReminderItem recurring=new ReminderItem();recurring.kind=ReminderItem.ScheduleKind.INTERVAL;recurring.intervalSeconds=3000;recurring.nextTriggerEpochMs=System.currentTimeMillis()+3000000;manager.upsert(recurring);manager.setEnabled(recurring.id,false);check(ReminderPanel.category(manager.get(recurring.id))==1,"disabled recurring is not completed");manager.setEnabled(recurring.id,true);check(ReminderPanel.category(manager.get(recurring.id))==0,"same rule re-enabled");manager.setPinned(recurring.id,true);check(manager.list().get(0).id.equals(recurring.id),"pin order");
  ReminderItem template=manager.saveTemplate(once.id);check(template.lifecycle==ReminderItem.Lifecycle.TEMPLATE&&!template.enabled&&!template.id.equals(once.id),"template independent and inactive");ReminderItem fresh=manager.freshCopy(template.id);check(fresh.enabled&&fresh.lifecycle==ReminderItem.Lifecycle.CURRENT&&!fresh.id.equals(template.id)&&fresh.nextTriggerEpochMs>System.currentTimeMillis(),"reuse has new identity and future time");
  ReminderItem sequence=new ReminderItem();sequence.kind=ReminderItem.ScheduleKind.SEQUENCE;sequence.sequenceSeconds=new ArrayList<>(List.of(300,600,1200,1800));List<ReminderItem> occurrences=new ArrayList<>();manager.setDueHandler(occurrences::add);
  for(int i=0;i<4;i++){sequence.nextTriggerEpochMs=System.currentTimeMillis()-10-i;manager.upsert(sequence);tick(manager);sequence=manager.get(sequence.id);}
  check(sequence.awaitingCompletion&&sequence.sequenceIndex==4,"finite sequence awaits final close");manager.completePresentation(occurrences.get(0));check(manager.get(sequence.id).lifecycle==ReminderItem.Lifecycle.CURRENT,"earlier queued close cannot complete final occurrence");manager.completePresentation(occurrences.get(3));check(manager.get(sequence.id).lifecycle==ReminderItem.Lifecycle.COMPLETED,"final occurrence closes archive");
  ReminderItem paused=new ReminderItem();paused.kind=ReminderItem.ScheduleKind.SEQUENCE;paused.enabled=false;paused.sequenceIndex=1;paused.lastTriggeredEpochMs=System.currentTimeMillis()-1000;paused.nextTriggerEpochMs=System.currentTimeMillis()+600000;manager.upsert(paused);
  ReminderItem legacy=new ReminderItem();legacy.enabled=false;legacy.lastTriggeredEpochMs=System.currentTimeMillis()-1000;legacy.nextTriggerEpochMs=legacy.lastTriggeredEpochMs;manager.upsert(legacy);
  ReminderItem expired=new ReminderItem();expired.enabled=false;expired.nextTriggerEpochMs=System.currentTimeMillis()-10000;manager.upsert(expired);manager.shutdown();ReminderManager reload=new ReminderManager(store);check(reload.get(expired.id).lifecycle==ReminderItem.Lifecycle.EXPIRED,"expired untriggered item not falsely completed");check(reload.get(template.id).lifecycle==ReminderItem.Lifecycle.TEMPLATE&&reload.get(recurring.id).pinned,"metadata persisted");check(reload.get(paused.id).lifecycle==ReminderItem.Lifecycle.CURRENT&&ReminderPanel.category(reload.get(paused.id))==1,"paused unfinished sequence remains stopped after reload");check(reload.get(legacy.id).lifecycle==ReminderItem.Lifecycle.ENDED,"legacy trigger is not assumed acknowledged");check(reload.list().size()==7,"recurrences do not duplicate definitions");reload.shutdown();
  ReminderManager overdue=new ReminderManager(new ReminderStore(root.resolve("fully-overdue.properties")));ReminderItem past=new ReminderItem();past.kind=ReminderItem.ScheduleKind.SEQUENCE;past.nextTriggerEpochMs=System.currentTimeMillis()-4*3600000L;overdue.upsert(past);List<ReminderItem> oldDeliveries=new ArrayList<>();overdue.setDueHandler(oldDeliveries::add);tick(overdue);overdue.completePresentation(oldDeliveries.get(0));check(overdue.get(past.id).lifecycle==ReminderItem.Lifecycle.COMPLETED,"fully overdue sequence accepts actual delivered occurrence token");overdue.shutdown();
  System.out.println("PASS final-overlay acknowledgement, restart recovery, sequence occurrence identity, expired vs disabled, pinning, inactive templates and safe reuse");System.exit(0);
 }
}
